class UserDto
  # Chỉ cho phép đọc: Đảm bảo tính đóng gói bất biến
  attr_reader :id, :created_at

  # Cho phép cả đọc và ghi
  attr_accessor :status

  def initialize(id:, status:)
    @id = id
    @status = status
    @created_at = Time.now.utc.freeze
  end

  # Setter tùy biến có validation nghiệp vụ thay vì dùng raw attr_writer
  def status=(new_status)
    raise ArgumentError, "Invalid status" unless %w[active pending suspended].include?(new_status)
    @status = new_status
  end
end

user = UserDto.new(id: 101, status: "pending")
puts user.id          # => 101 (getter hoạt động)
