user.status = "active" # => Cập nhật thành công

# Cài đặt Result Monad thuần túy (Không cần cài thêm gem)
class Result
  attr_reader :value

  def initialize(success, value)
    @success = success
    @value = value
  end

  def success? = @success
  def failure? = !@success

  # Monadic bind (and_then)
  def bind
    success? ? yield(@value) : self
  end
end

def Success(val) = Result.new(true, val)
def Failure(err) = Result.new(false, err)

# Quy trình thanh toán theo chuẩn Railway-Oriented
class CheckoutWorkflow
  def self.call(cart_id:, user:)
    find_cart(cart_id)
      .bind { |cart| reserve_inventory(cart) }
      .bind { |cart| charge_credit_card(user, cart) }
      .bind { |order| send_receipt(order) }
  end

  def self.find_cart(id) = id > 0 ? Success({ id: id, total: 150 }) : Failure(:cart_not_found)
  def self.reserve_inventory(cart) = Success(cart.merge(reserved: true))
  def self.charge_credit_card(user, cart) = Failure(:insufficient_funds) # Giả lập lỗi tại bước 3
  def self.send_receipt(order) = Success(:completed)
end

outcome = CheckoutWorkflow.call(cart_id: 1, user: "Nam")
if outcome.success?
  puts "Checkout OK: #{outcome.value}"
else
  puts "Checkout Halted at failure step: #{outcome.value}" # => :insufficient_funds
end
